import React, { useEffect, useState } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  Container,
  Box,
  Card,
  CardContent,
  Paper,
  Grid,
  ToggleButton,
  ToggleButtonGroup,
} from "@mui/material";

function App() {
  const [sfData, setSfData] = useState(null);
  
  // State initialized to null so there is no default selection
  const [selectedOption, setSelectedOption] = useState(null);

  useEffect(() => {
    const handleMessage = (event) => {
      if (!event.origin.includes("sandbox.vf.force.com")) return;

      console.log("Raw data received:", event.data);

      let parsedData;

      try {
        parsedData =
          typeof event.data === "string"
            ? JSON.parse(event.data)
            : event.data;

        console.log("Parsed data:", parsedData);
        setSfData(parsedData);
      } catch (error) {
        console.error("Error parsing message data:", error);
      }
    };

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, []);

  // Handler for the horizontal options
  const handleOptionChange = (event, newOption) => {
    if (newOption !== null) {
      setSelectedOption(newOption);
    }
  };

  return (
    <Box sx={{ backgroundColor: "#f4f6f8", minHeight: "100vh" }}>
      
      {/* Header */}
      <AppBar position="static">
        <Toolbar>
          <Typography variant="h6" sx={{ flexGrow: 1, textAlign: "center" }}>
            IAG POC - Salesforce Integration with I frame
          </Typography>
        </Toolbar>
      </AppBar>

      <Container maxWidth="lg" sx={{ mt: 4,  pb: 4 }}>

        <Paper
          elevation={4}
          sx={{
            padding: 3,
            borderRadius: 3,
            mb: 4,
            backgroundColor: "#ffffff",
          }}
        >
          <Typography variant="h6" gutterBottom align="center">
            {sfData ? "Customer Found - Proceed to Payment" : "Search for a Customer"}
          </Typography>

          {/* Grid Container for Vertical Stack */}
          <Grid container spacing={3}>
            
            {/* Top Section: Search Iframe */}
            <Grid item xs={12}>
              <Typography variant="subtitle2" color="textSecondary" sx={{ mb: 1 }}>
                Search Customer
              </Typography>
              <Box
                sx={{
                  border: "2px solid #1976d2",
                  borderRadius: 2,
                  overflow: "hidden",
                }}
              >
                <iframe
                  src="https://racv--cbqa--c.sandbox.vf.force.com/apex/ExternalCustomerManagerVF"
                  width="100%"
                  height="500px"
                  style={{ border: "none" }}
                  title="Search Iframe"
                />
              </Box>
            </Grid>

            {/* Bottom Section: Payment Iframe (Only shows if sfData is present) */}
            {sfData && (
              <Grid item xs={12}>
                 <Typography variant="subtitle2" color="textSecondary" sx={{ mb: 1 }}>
                  Payment Setup for {sfData.Name}
                </Typography>
                <Box
                  sx={{
                    border: "2px solid #2e7d32",
                    borderRadius: 2,
                    overflow: "hidden",
                  }}
                >
                  <iframe
                    src={`https://racv--cbqa--c.sandbox.vf.force.com/apex/ExternalCustomerPaymentVF?id=${sfData.Id}`}
                    width="100%"
                    height="550px"
                    style={{ border: "none" }}
                    title="Payment Iframe"
                  />
                </Box>
              </Grid>
            )}
          </Grid>
        </Paper>

        {/* Data Display Section */}
        <Card elevation={3} sx={{ borderRadius: 3, mb: 4 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Data Received From Salesforce
            </Typography>

            {sfData ? (
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <Typography><strong>ID:</strong> {sfData.Id}</Typography>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography><strong>Name:</strong> {sfData.Name}</Typography>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography><strong>Email:</strong> {sfData.PersonEmail}</Typography>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography><strong>Mobile:</strong> {sfData.PersonMobilePhone}</Typography>
                </Grid>
              </Grid>
            ) : (
              <Typography color="text.secondary">
                No data received yet...
              </Typography>
            )}
          </CardContent>
        </Card>

        {/* New Knowledge Article Section */}
        <Paper
          elevation={4}
          sx={{
            padding: 3,
            borderRadius: 3,
            backgroundColor: "#ffffff",
          }}
        >
          <Typography variant="h6" gutterBottom align="center">
            Knowledge Articles
          </Typography>

          <Grid container spacing={3}>
            {/* 1. Top item: Horizontal selections */}
            <Grid item xs={12} sx={{ display: "flex", justifyContent: "center" }}>
              <ToggleButtonGroup
                color="primary"
                value={selectedOption}
                exclusive
                onChange={handleOptionChange}
                aria-label="Knowledge Article Options"
              >
                <ToggleButton value="BUILDING">BUILDING</ToggleButton>
                <ToggleButton value="CONTENTS">CONTENTS</ToggleButton>
                <ToggleButton value="COMBINED">COMBINED</ToggleButton>
                <ToggleButton value="LANDLORD">LANDLORD</ToggleButton>
              </ToggleButtonGroup>
            </Grid>

            {/* 2. Bottom item: Dynamic Iframe (Only loads when an option is selected) */}
            {selectedOption && (
              <Grid item xs={12}>
                <Box
                  sx={{
                    border: "2px solid #9c27b0",
                    borderRadius: 2,
                    overflow: "hidden",
                  }}
                >
                  <iframe
                    src={`https://racv--cbqa--c.sandbox.vf.force.com/apex/ExternalKnowledgeArticleVF?title=${encodeURIComponent(selectedOption)}`}
                    width="100%"
                    height="400px"
                    style={{ border: "none" }}
                    title="Knowledge Article Iframe"
                  />
                </Box>
              </Grid>
            )}
          </Grid>
        </Paper>

      </Container>
      
    </Box>
  );
}

export default App;